'use strict';
/* bored? — languages.
   English is the source text: app.js wraps it in T('…'), and NL maps that English to Dutch.
   Placeholders like {n} are filled in after translating. Tn() picks the singular or plural form.
   TS() translates text that comes from the server (errors, bonus labels, feed lines).
   Adding or changing English text in app.js? Add the Dutch line here too
   (`node test/i18n.js` lists anything missing). */

const LANGS = { en: 'English', nl: 'Nederlands' };
const LANG = (() => {
  try { const v = JSON.parse(localStorage.getItem('bored.lang')); if (LANGS[v]) return v; } catch { /* private mode */ }
  return /^nl\b/i.test(navigator.language || '') ? 'nl' : 'en';
})();
const LOCALE = LANG === 'nl' ? 'nl-BE' : undefined;
document.documentElement.lang = LANG;
const I18N_MISSING = new Set();   // for tests: English text that had no Dutch line

const fill = (s, v) => (v ? s.replace(/\{(\w+)\}/g, (m, k) => (k in v ? v[k] : m)) : s);
function T(s, v) {
  let out = s;
  if (LANG === 'nl') { if (NL[s] === undefined) I18N_MISSING.add(s); else out = NL[s]; }
  return fill(out, v);
}
function Tn(n, one, other, v) {
  return T(n === 1 ? one : other, { n: new Intl.NumberFormat(LOCALE).format(n), ...v });
}
function TS(s) {
  if (LANG === 'en' || !s) return s;
  if (NL[s] !== undefined) return NL[s];
  for (const [re, f] of NL_PATTERNS) { const m = s.match(re); if (m) return f(m); }
  I18N_MISSING.add(s);
  return s;
}

// "12.5 h" from the server → "12,5 u"
const nlHours = (s) => s.replace(/(\d+)\.(\d+)/g, '$1,$2').replace(/ h\b/g, ' u');
const nlWait = (s) => s.replace(/^(\d+) seconds$/, '$1 seconden').replace(/^(\d+) minutes$/, '$1 minuten');
const nlField = (f) => NL[f] || f;
const achName = (n) => NL[n] || n;

const NL_PATTERNS = [
  // input checks
  [/^(.+) can be at most (\d+) characters$/, (m) => `${nlField(m[1])} mag hoogstens ${m[2]} tekens lang zijn`],
  [/^(.+) needs at least (\d+) characters?$/, (m) => `${nlField(m[1])} moet minstens ${m[2]} ${m[2] === '1' ? 'teken' : 'tekens'} lang zijn`],
  [/^(.+) must be between (-?\d+) and (-?\d+)$/, (m) => `${nlField(m[1])} moet tussen ${m[2]} en ${m[3]} liggen`],
  [/^(.+) must be a whole number$/, (m) => `${nlField(m[1])} moet een geheel getal zijn`],
  [/^(.+) is missing$/, (m) => `${nlField(m[1])} ontbreekt`],
  [/^Password needs at least (\d+) characters\. A few random words works well\.$/, (m) => `Je wachtwoord moet minstens ${m[1]} tekens lang zijn. Een paar willekeurige woorden werkt goed.`],
  [/^Not unlocked yet\. Log (.+) more first\.$/, (m) => `Nog niet vrijgespeeld. Noteer eerst nog ${nlHours(m[1])}.`],
  [/^Slow down a little\. Try again in (.+)\.$/, (m) => `Rustig aan. Probeer het opnieuw over ${nlWait(m[1])}.`],
  [/^Too many attempts\. Try again in (.+)\.$/, (m) => `Te veel pogingen. Probeer het opnieuw over ${nlWait(m[1])}.`],
  [/^Too many wrong passwords for this account\. Try again in (.+)\.$/, (m) => `Te veel foute wachtwoorden voor dit account. Probeer het opnieuw over ${nlWait(m[1])}.`],
  [/^You and (.+) are already friends$/, (m) => `Jij en ${m[1]} zijn al vrienden`],
  // bonus labels from a session
  [/^(\d+)-day streak$/, (m) => `Reeks van ${m[1]} dagen`],
  [/^Dusted off after (\d+) days$/, (m) => `Afgestoft na ${m[1]} dagen`],
  [/^Rediscovered after (\d+) days$/, (m) => `Herontdekt na ${m[1]} dagen`],
  // high-fives (“so-and-so high-fived …”)
  [/^your (\d+)-day streak$/, (m) => `je reeks van ${m[1]} dagen`],
  [/^a (\d+)-day streak$/, (m) => `een reeks van ${m[1]} dagen`],
  [/^your “(.+)” badge$/, (m) => `je badge “${achName(m[1])}”`],
  [/^an “(.+)” badge$/, (m) => `een badge “${achName(m[1])}”`],
  // friends’ moments (“Lisa …”)
  [/^hit a (\d+)-day streak$/, (m) => `haalde een reeks van ${m[1]} dagen`],
  [/^unlocked “(.+)”$/, (m) => `behaalde “${achName(m[1])}”`],
  // signed-in devices
  [/^(\w+) on (.+)$/, (m) => `${m[1]} op ${NL[m[2]] || m[2]}`],
];

